// presentationIllustrator.ts
//
// 2026-06-17 - Runtime illustration resolver for the interactive #presentation.
//
// After the narrative composer emits a PresentationPayload, any section whose
// `data.imageConcept` is a non-empty string gets ONE tasteful, on-brand,
// TRANSPARENT flat-vector illustration (Illustrator skill) generated by the
// proxy (`POST /api/ai/illustration` -> Nano Banana 2 + knockout, persisted +
// cataloged in the image library, returns a reusable URL). The resolved URL is
// written back to `data.illustration` so the :5014 renderer can float it on the
// scene. The renderer prefixes the (relative) URL with its own PROXY_URL.
//
// Fail-open by design: a scene without an illustration is fine, so a failed or
// slow generation never blocks publishing the presentation. Exact concepts are
// reused from the library (the proxy returns the cached PNG on a hash match), so
// re-running a presentation costs nothing for unchanged scenes.

import type { PresentationPayload } from './presentationTypes';
import { normalizeBrandId } from '../components/slideTemplates/brands';
import { brandImageryHint } from './artifactIllustrator';

const PROXY_BASE = 'http://127.0.0.1:5012';

// Contrast follows the DECK CANVAS, not the section kind. The presentation
// renderer paints every section on `meta.theme`'s background (dark decks =
// near-black/navy ground), so a "light"-canvas (dark-subject) illustration
// would vanish. Default every illustration's canvas to the deck theme; a
// per-section `imageCanvas` may still override (e.g. a deliberately inverted
// band). This is the fix for "the visuals make no sense" - dark art on dark.
function canvasFor(deckTheme: 'dark' | 'light', explicit: unknown): 'dark' | 'light' {
  if (explicit === 'dark' || explicit === 'light') return explicit;
  return deckTheme;
}

// Layout slot per section kind - MUST match the renderer's SectionWrapper mapping
// (hero = focal graphic above title; context/cta/quotes = reserved side column;
// everything else = faint backdrop). The slot drives the VS layout-aware selection
// and the dedup key on the proxy.
const SIDE_KINDS = new Set(['context', 'cta', 'quotes']);
function slotFor(kind: string): 'hero' | 'side' | 'backdrop' {
  if (kind === 'hero') return 'hero';
  return SIDE_KINDS.has(kind) ? 'side' : 'backdrop';
}

/**
 * Generate + attach illustrations for every section carrying a non-empty
 * `imageConcept`. Mutates the payload's section data in place (sets
 * `data.illustration` to the proxy-relative image URL). Returns the number of
 * illustrations attached. Never throws - per-section failures are swallowed.
 */
export async function resolvePresentationIllustrations(
  payload: PresentationPayload,
  onLog?: (msg: string) => void,
): Promise<number> {
  // ONE normalizer for every brand spelling (NXT / NU / DECIEM); the proxy illustration prompt reads
  // the brand palette from this id (DECIEM = black and white, pink / cyan / purple pops, line-art).
  const brand = normalizeBrandId((payload?.meta as any)?.brand);
  const brandHint = brandImageryHint(brand);
  const deckTheme: 'dark' | 'light' = String((payload?.meta as any)?.theme || 'dark') === 'light' ? 'light' : 'dark';
  const sections = Array.isArray(payload?.sections) ? payload.sections : [];

  // Collect the sections that asked for art and don't already have it.
  const targets = sections.filter((s) => {
    const d = (s?.data || {}) as Record<string, unknown>;
    return typeof d.imageConcept === 'string'
      && (d.imageConcept as string).trim().length > 0
      && !d.illustration;
  });
  if (targets.length === 0) return 0;

  let attached = 0;
  // Sequential so the intra-deck uniqueness guard is race-free: NO two sections may show the same
  // image. The library still dedups by concept across decks (variant 0); within THIS deck, if a
  // returned URL was already used, bump `variant` (-> fresh VS sample -> distinct image) and retry.
  const usedUrls = new Set<string>();
  for (const s of targets) {
    const d = s.data as Record<string, unknown>;
    const concept = String(d.imageConcept).trim();
    const canvas = canvasFor(deckTheme, d.imageCanvas);
    const slot = slotFor(s.kind);
    try {
      let chosen = '';
      for (let variant = 0; variant <= 3 && !chosen; variant++) {
        const resp = await fetch(`${PROXY_BASE}/api/ai/illustration`, {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ concept, brand, canvas, slot, variant, brandHint: brandHint || undefined }),
        });
        if (!resp.ok) { onLog?.(`illustration HTTP ${resp.status} for "${concept.slice(0, 48)}"`); break; }
        const res = await resp.json();
        const url = (res && typeof res.url === 'string') ? res.url : '';
        if (!url) break;
        if (!usedUrls.has(url)) { chosen = url; break; }
        onLog?.(`illustration repeat on "${concept.slice(0, 32)}" - retrying (variant ${variant + 1})`);
      }
      if (chosen) {
        usedUrls.add(chosen);
        d.illustration = chosen;        // relative proxy path; renderer prefixes PROXY_URL
        d.illustrationCanvas = canvas;  // hint for the renderer's contrast/placement
        attached++;
        onLog?.(`illustration attached (${s.kind})`);
      }
    } catch (e: any) {
      onLog?.(`illustration skipped (${s.kind}): ${e?.message || e}`);
    }
  }
  return attached;
}
